import { Response, NextFunction } from 'express';
import { Op } from 'sequelize';
import { User } from '../models/user.model';
import { IAuthRequest } from '../interfaces/auth.interface';

// Define a type that makes password optional
type SafeUser = Omit<User, 'password'> & {
  password?: string;
};

export class UserController {
  /**
   * Cập nhật vai trò người dùng (chỉ admin)
   */
  public static async updateUserRole(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { id } = req.params;
      const { role } = req.body;

      // Validate role
      if (!['admin', 'editor', 'user'].includes(role)) {
        return res.status(400).json({
          success: false,
          message: 'Vai trò không hợp lệ. Vui lòng chọn một trong các vai trò: admin, editor, user',
        });
      }

      // Không cho phép tự thay đổi vai trò của chính mình
      if (req.user?.id === id) {
        return res.status(400).json({
          success: false,
          message: 'Không thể thay đổi vai trò của chính bạn',
        });
      }

      const user = await User.findByPk(id);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }

      // Cập nhật vai trò
      user.role = role as any;
      await user.save();

      // Sử dụng kiểu SafeUser để xử lý password
      const userJson = user.toJSON() as SafeUser;
      if ('password' in userJson) {
        delete userJson.password;
      }

      return res.status(200).json({
        success: true,
        message: 'Cập nhật vai trò thành công',
        data: userJson,
      });
    } catch (error) {
      next(error);
    }
  }

  /**
   * Kích hoạt/vô hiệu hóa tài khoản người dùng (chỉ admin)
   */
  public static async toggleUserStatus(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { id } = req.params;
      const { is_active } = req.body;

      // Không cho phép tự vô hiệu hóa tài khoản của chính mình
      if (req.user?.id === id) {
        return res.status(400).json({
          success: false,
          message: 'Không thể thay đổi trạng thái tài khoản của chính bạn',
        });
      }

      const user = await User.findByPk(id);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }

      // Cập nhật trạng thái
      user.is_active = is_active;
      await user.save();

      // Sử dụng kiểu SafeUser để xử lý password
      const userJson = user.toJSON() as SafeUser;
      if ('password' in userJson) {
        delete userJson.password;
      }

      return res.status(200).json({
        success: true,
        message: `Đã ${is_active ? 'kích hoạt' : 'vô hiệu hóa'} tài khoản thành công`,
        data: userJson,
      });
    } catch (error) {
      next(error);
    }
  }

  /**
   * Xóa người dùng (chỉ admin)
   */
  public static async deleteUser(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { id } = req.params;

      // Không cho phép tự xóa tài khoản của chính mình
      if (req.user?.id === id) {
        return res.status(400).json({
          success: false,
          message: 'Không thể xóa tài khoản của chính bạn',
        });
      }

      const user = await User.findByPk(id);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }

      // Thực hiện xóa mềm
      await user.destroy();

      return res.status(200).json({
        success: true,
        message: 'Đã xóa người dùng thành công',
      });
    } catch (error) {
      next(error);
    }
  }

  // ... (other methods remain the same)


  /**
   * Tạo người dùng mới (admin)
   */
  public static async createUser(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { email, password, full_name, role = 'user' } = req.body;

      // Kiểm tra email đã tồn tại chưa
      const existingUser = await User.findOne({ where: { email } });
      if (existingUser) {
        return res.status(400).json({
          success: false,
          message: 'Email đã được sử dụng',
        });
      }

      // Tạo người dùng mới
      const user = await User.create({
        email,
        password,
        full_name,
        role,
        is_active: true,
        email_verified: true,
        login_attempts: 0,
        lock_until: null,
      } as any);

      // Sử dụng kiểu SafeUser để xử lý password
      const userJson = user.toJSON() as SafeUser;
      if ('password' in userJson) {
        delete userJson.password;
      }

      return res.status(201).json({
        success: true,
        data: userJson,
      });
    } catch (error) {
      next(error);
    }
  }

  /**
   * Cập nhật thông tin người dùng
   */
  public static async updateUser(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { id } = req.params;
      const { email, full_name, role } = req.body;

      const user = await User.findByPk(id);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }

      // Cập nhật thông tin
      if (email) user.email = email;
      if (full_name) user.full_name = full_name;
      if (role) user.role = role as any;

      await user.save();

      // Sử dụng kiểu SafeUser để xử lý password
      const userJson = user.toJSON() as SafeUser;
      if ('password' in userJson) {
        delete userJson.password;
      }

      return res.status(200).json({
        success: true,
        data: userJson,
      });
    } catch (error) {
      next(error);
    }
  }

  /**
   * Đổi mật khẩu
   */
  public static async changePassword(req: IAuthRequest, res: Response, next: NextFunction): Promise<Response | void> {
    try {
      const { currentPassword, newPassword } = req.body;
      const userId = req.user?.id;

      if (!userId) {
        return res.status(401).json({
          success: false,
          message: 'Không tìm thấy thông tin xác thực',
        });
      }

      const user = await User.findByPk(userId);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'Không tìm thấy người dùng',
        });
      }

      // Kiểm tra mật khẩu hiện tại
      const isMatch = await user.comparePassword(currentPassword);
      if (!isMatch) {
        return res.status(400).json({
          success: false,
          message: 'Mật khẩu hiện tại không đúng',
        });
      }

      // Cập nhật mật khẩu mới
      user.password = newPassword;
      await user.save();

      return res.status(200).json({
        success: true,
        message: 'Đổi mật khẩu thành công',
      });
    } catch (error) {
      next(error);
    }
  }
}

export default UserController;
